// Cursor app identity helper v3. Generated by Cursor. Do not edit: publish-app keeps it current.
// Tells a private or team app who its signed-in viewer is. Call requireIdentity(request) in a route handler, or getIdentity(request) when a viewer is optional.
// getIdentity, requireIdentity and verifyIdentity return a signed-in person (userId) or an API key the gate admitted (kind "person" or "key"; a key has ownerUserId or ownerTeamId). On a team app a key's teamRole is "service": requireTeamRole matches roles exactly, so "admin" and "member" refuse keys; list "service" to admit them.
// On the published host, functions use the web signature (export async function GET(request)), so pass that web Request. The Node form, getIdentity(req) with req.headers a plain object, is for local servers such as http.createServer or Express; a bare Headers object or headers object also works.
// Locally, with neither CURSOR_APP_ID nor VERCEL set, a request without the header reads as the simulated viewer in ./identity.dev (simulated: true, empty token). A deployed app never takes that branch.

import { DEV_VIEWER } from "./identity.dev.js";

const IDENTITY_HEADER = "x-cursor-identity-v2";
const DEFAULT_ISSUER = "https://api.cursor.com/apps/identity";
const DEV_ISSUER = "cursor:dev";
const PERSON_HEADER = "x-cursor-identity";
const IDENTITY_VERSION = 2;
const CLOCK_TOLERANCE_SECONDS = 60;
const FETCH_TIMEOUT_MS = 5000;
const JWKS_REFETCH_COOLDOWN_MS = 60000;
const DEV_VIEWER_TTL_MS = 300000;

/** The shape ./identity.dev exports: the viewer a local dev server simulates, or null for the signed-out state. */
export type DevViewer = {
  /** Opaque; "user:<id>" is the form the gate mints. */
  sub: string;
  email: string;
  name?: string;
  /** Both together make a team viewer; neither makes a private-app viewer. */
  teamId?: number;
  teamRole?: TeamRole;
};

export type IdentityFailureReason =
  | "missing_header"
  | "app_id_unset"
  | "issuer_unreachable"
  | "malformed_token"
  | "bad_signature"
  | "unknown_key"
  | "wrong_audience"
  | "wrong_issuer"
  | "expired"
  | "invalid_claims"
  | "dev_viewer_invalid";

export type TeamRole = "admin" | "member";

/**
 * The team role an API key caller carries when it has a team. It looks like a
 * membership role, but no team member holds it, so it never means the caller
 * is a member or an admin. requireTeamRole admits it only when roles lists it.
 */
export type KeyTeamRole = "service";

/** Which host served the request: the app's own, or its preview of the working copy. */
export type IdentityStage = "production" | "preview";

export type IdentityClaims = Record<string, unknown>;

type IdentityBase = {
  verified: true;
  /** False when the gate's signed token named the viewer. True only in local development, where the viewer came from ./identity.dev and nothing verified it; token is then "". */
  simulated: boolean;
  /** The raw token. Forward it to your own backend and verify it there with verifyIdentity. Empty for a simulated viewer. */
  token: string;
  /** Opaque and stable per viewer. Use it as the key for per-viewer data. Never parse it. */
  sub: string;
  /** Empty when the viewer's session has no email; emailVerified is then false. */
  email: string;
  emailVerified: boolean;
  /** Empty when unknown. */
  name: string;
  idp: { provider: "cursor"; sub: string };
  /** "preview" on the app's preview host: keep preview traffic out of production data. */
  stage: IdentityStage;
  expiresAt: Date;
  claims: IdentityClaims;
};

/** A signed-in person. userId is the Cursor user id in sub ("user:<id>"); 0 for a simulated viewer whose sub carries none. */
export type PersonIdentity = IdentityBase & { kind: "person"; userId: number } &
  ({ appVisibility: "private" } | { appVisibility: "team"; teamId: number; teamRole: TeamRole });

/**
 * An API key the gate admitted, never a person: email is empty and name is the
 * key's name. ownerUserId names a personal key's owner, ownerTeamId a team
 * key's team. On a team app it carries the app's team with teamRole "service";
 * on private and public apps it carries no team.
 */
export type KeyIdentity = IdentityBase & { kind: "key"; email: ""; emailVerified: false } &
  ({ ownerUserId: number; ownerTeamId?: undefined } | { ownerTeamId: number; ownerUserId?: undefined }) &
  ({ appVisibility: "private" | "public" } | { appVisibility: "team"; teamId: number; teamRole: KeyTeamRole });

/** A person or an API key; identity.kind tells them apart. */
export type VerifiedIdentity = PersonIdentity | KeyIdentity;

export type TeamIdentity = Extract<VerifiedIdentity, { appVisibility: "team" }>;

export type UnverifiedIdentity = { verified: false; reason: IdentityFailureReason };

export type Identity = VerifiedIdentity | UnverifiedIdentity;

export class IdentityError extends Error {
  readonly status: 401 | 403;
  readonly reason: IdentityFailureReason | "forbidden";

  constructor(status: 401 | 403, reason: IdentityFailureReason | "forbidden") {
    super("cursor identity: " + reason);
    this.name = "IdentityError";
    this.status = status;
    this.reason = reason;
  }
}

export type RequireOptions = {
  /** "response" (default) returns a 401 or 403 Response; "throw" throws an IdentityError. */
  onFailure?: "response" | "throw";
};

/** A header value as Node's IncomingMessage and most server frameworks expose it. */
export type HeaderValue = string | string[] | undefined;

/**
 * Where the identity header is read from: anything with a get(name) method,
 * such as a web Headers object, or a plain object keyed by header name, such
 * as the headers of a Node http request.
 */
export type HeadersLike =
  | { get(name: string): string | null | undefined }
  | Record<string, HeaderValue>;

/**
 * What getIdentity and requireIdentity accept: a web Request, a Node http
 * request or any framework request that keeps its headers on .headers, or
 * the headers themselves.
 */
export type IdentityRequest = { headers: HeadersLike } | HeadersLike;

/** Reads the identity header from a web Request, a Node http request (req.headers) or a headers object. Never throws; an absent or bad header gives { verified: false }, except on a local dev server, where an absent header gives the simulated viewer from ./identity.dev with simulated: true. */
export async function getIdentity(request: IdentityRequest): Promise<Identity> {
  const token = identityHeader(request, IDENTITY_HEADER);
  if (token !== undefined && token !== "") {
    return verifyToken(token, "v2");
  }
  // x-cursor-identity never carries an API key, so its token reads as a person.
  const personToken = identityHeader(request, PERSON_HEADER);
  if (personToken === undefined || personToken === "") {
    return devViewer();
  }
  return verifyToken(personToken, "person");
}

export async function requireIdentity(
  request: IdentityRequest,
  options: { onFailure: "throw" },
): Promise<VerifiedIdentity>;
export async function requireIdentity(
  request: IdentityRequest,
  options?: { onFailure?: "response" },
): Promise<VerifiedIdentity | Response>;
export async function requireIdentity(
  request: IdentityRequest,
  options: RequireOptions = {},
): Promise<VerifiedIdentity | Response> {
  const identity = await getIdentity(request);
  if (identity.verified) {
    return identity;
  }
  return fail(401, identity.reason, options);
}

/**
 * The identity when its team role is one of roles, matched exactly, or a 403.
 * An API key's role is "service", so ["admin"] and ["member"] refuse every
 * key; list "service" to let the app's API keys through.
 */
export function requireTeamRole<R extends TeamRole | KeyTeamRole>(
  identity: VerifiedIdentity,
  roles: readonly R[],
  options: { onFailure: "throw" },
): TeamIdentity & { teamRole: R };
export function requireTeamRole<R extends TeamRole | KeyTeamRole>(
  identity: VerifiedIdentity,
  roles: readonly R[],
  options?: { onFailure?: "response" },
): (TeamIdentity & { teamRole: R }) | Response;
export function requireTeamRole(
  identity: VerifiedIdentity,
  roles: readonly (TeamRole | KeyTeamRole)[],
  options: RequireOptions = {},
): TeamIdentity | Response {
  if (identity.appVisibility === "team" && roles.includes(identity.teamRole)) {
    return identity;
  }
  return fail(403, "forbidden", options);
}

/**
 * Verifies a raw token, for example one your frontend forwarded to your own backend. Never throws.
 * A token with neither ver nor kind is the person-only format of x-cursor-identity and reads as a person.
 */
export async function verifyIdentity(token: string): Promise<Identity> {
  return verifyToken(token, "forwarded");
}

/** Where a token came from: x-cursor-identity-v2, x-cursor-identity, or a caller of verifyIdentity. */
type TokenSource = "v2" | "person" | "forwarded";

async function verifyToken(token: string, source: TokenSource): Promise<Identity> {
  const appId = trimmed(typeof process === "undefined" ? undefined : process.env.CURSOR_APP_ID);
  if (appId === "") {
    return { verified: false, reason: "app_id_unset" };
  }
  if (typeof token !== "string" || token === "") {
    return { verified: false, reason: "malformed_token" };
  }
  const issuer = (
    trimmed(typeof process === "undefined" ? undefined : process.env.CURSOR_APP_IDENTITY_ISSUER) ||
    DEFAULT_ISSUER
  ).replace(/\/$/, "");
  const parsed = parseToken(token);
  if (parsed === undefined) {
    return { verified: false, reason: "malformed_token" };
  }
  let key: CryptoKey | undefined;
  try {
    key = await keyFor(issuer, parsed.kid);
  } catch {
    return { verified: false, reason: "issuer_unreachable" };
  }
  if (key === undefined) {
    return { verified: false, reason: "unknown_key" };
  }
  const valid = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", key, parsed.signature, parsed.signed);
  if (!valid) {
    return { verified: false, reason: "bad_signature" };
  }
  const { iss, aud, exp, nbf } = parsed.claims;
  if (iss !== issuer) {
    return { verified: false, reason: "wrong_issuer" };
  }
  if (!(aud === appId || (Array.isArray(aud) && aud.includes(appId)))) {
    return { verified: false, reason: "wrong_audience" };
  }
  const now = Date.now() / 1000;
  if (typeof exp !== "number" || (nbf !== undefined && typeof nbf !== "number")) {
    return { verified: false, reason: "invalid_claims" };
  }
  if (exp + CLOCK_TOLERANCE_SECONDS < now) {
    return { verified: false, reason: "expired" };
  }
  if (typeof nbf === "number" && nbf - CLOCK_TOLERANCE_SECONDS > now) {
    return { verified: false, reason: "invalid_claims" };
  }
  return identityFromClaims(token, parsed.claims, source);
}

// Env reads stay static (process.env.NAME) so bundlers that inline them at build time, such as edge and middleware builds, keep them.
function trimmed(value: string | undefined): string {
  return typeof value === "string" ? value.trim() : "";
}

/**
 * What a request without the header resolves to. In a deployed app that is
 * missing_header, always: CURSOR_APP_ID is set by the platform for every
 * published app, and VERCEL by the host, so either one being present
 * ends the dev path before the sibling's viewer is even looked at, so the
 * sibling publishing with the app changes nothing in production. Only when
 * both are absent does the helper return that viewer, marked simulated,
 * with an empty token so a forwarded token fails closed. The viewer never
 * comes from the request, so a visitor cannot choose it.
 */
function devViewer(): Identity {
  if (typeof process === "undefined") {
    return { verified: false, reason: "missing_header" };
  }
  if (trimmed(process.env.CURSOR_APP_ID) !== "" || trimmed(process.env.VERCEL) !== "") {
    return { verified: false, reason: "missing_header" };
  }
  const value: unknown = DEV_VIEWER;
  if (value === null || value === undefined) {
    return { verified: false, reason: "missing_header" };
  }
  if (typeof value !== "object" || Array.isArray(value)) {
    return { verified: false, reason: "dev_viewer_invalid" };
  }
  const { sub, email, name, teamId, teamRole } = value as Record<string, unknown>;
  if (
    typeof sub !== "string" ||
    sub === "" ||
    typeof email !== "string" ||
    (name !== undefined && typeof name !== "string")
  ) {
    return { verified: false, reason: "dev_viewer_invalid" };
  }
  const now = Date.now();
  const idpSub = sub.startsWith("user:") ? sub.slice("user:".length) : sub;
  const claims: IdentityClaims = {
    iss: DEV_ISSUER,
    sub,
    iat: Math.floor(now / 1000),
    exp: Math.floor((now + DEV_VIEWER_TTL_MS) / 1000),
    email,
    email_verified: email !== "",
    name: name ?? "",
    idp: { provider: "cursor", sub: idpSub },
    kind: "person",
    ver: IDENTITY_VERSION,
  };
  const base = {
    verified: true as const,
    simulated: true,
    token: "",
    sub,
    kind: "person" as const,
    userId: Number(/^user:(\d+)$/.exec(sub)?.[1] ?? 0),
    email,
    emailVerified: email !== "",
    name: name ?? "",
    idp: { provider: "cursor" as const, sub: idpSub },
    stage: "production" as const,
    expiresAt: new Date(now + DEV_VIEWER_TTL_MS),
    claims,
  };
  if (teamId === undefined && teamRole === undefined) {
    claims.app_visibility = "private";
    return { ...base, appVisibility: "private" };
  }
  if (typeof teamId === "number" && (teamRole === "admin" || teamRole === "member")) {
    claims.app_visibility = "team";
    claims.team_id = teamId;
    claims.team_role = teamRole;
    return { ...base, appVisibility: "team", teamId, teamRole };
  }
  return { verified: false, reason: "dev_viewer_invalid" };
}

/** The identity header's value wherever the request keeps its headers; undefined when there is none or the input is not a request. */
function identityHeader(request: IdentityRequest, header: string): string | undefined {
  if (typeof request !== "object" || request === null) {
    return undefined;
  }
  const headers = headersOf(request);
  if (hasGet(headers)) {
    const value = headers.get(header);
    return typeof value === "string" ? value : undefined;
  }
  let value: HeaderValue = headers[header];
  if (value === undefined) {
    // Node lowercases incoming header names; a copy made elsewhere may keep the sender's casing.
    const key = Object.keys(headers).find((name) => name.toLowerCase() === header);
    value = key === undefined ? undefined : headers[key];
  }
  if (Array.isArray(value)) {
    // A repeated header reads as one comma-joined value, as Headers.get does, and then fails as malformed_token.
    value = value.join(", ");
  }
  return typeof value === "string" ? value : undefined;
}

/** A request's .headers when it has one; otherwise the input is taken to be the headers. */
function headersOf(request: IdentityRequest): HeadersLike {
  const nested: unknown = (request as { headers?: unknown }).headers;
  if (typeof nested === "object" && nested !== null && !Array.isArray(nested)) {
    return nested as HeadersLike;
  }
  return request as HeadersLike;
}

function hasGet(headers: HeadersLike): headers is { get(name: string): string | null | undefined } {
  return typeof (headers as { get?: unknown }).get === "function";
}

function fail(
  status: 401 | 403,
  reason: IdentityFailureReason | "forbidden",
  options: RequireOptions,
): Response {
  if (options.onFailure === "throw") {
    throw new IdentityError(status, reason);
  }
  return new Response(JSON.stringify({ error: status === 401 ? "unauthorized" : "forbidden", reason }), {
    status,
    headers: { "content-type": "application/json" },
  });
}

type ParsedToken = {
  kid: string | undefined;
  claims: IdentityClaims;
  /** The bytes the signature covers: header, dot, payload. */
  signed: BufferSource;
  signature: BufferSource;
};

/** Splits and decodes a compact JWS with alg RS256; undefined for anything else. */
function parseToken(token: string): ParsedToken | undefined {
  const parts = token.split(".");
  if (parts.length !== 3) {
    return undefined;
  }
  const [headerPart, payloadPart, signaturePart] = parts;
  const header = decodeJson(headerPart);
  const claims = decodeJson(payloadPart);
  const signature = decodeBase64Url(signaturePart);
  if (header === undefined || claims === undefined || signature === undefined) {
    return undefined;
  }
  if (header.alg !== "RS256" || (header.kid !== undefined && typeof header.kid !== "string")) {
    return undefined;
  }
  return {
    kid: header.kid,
    claims,
    signed: new TextEncoder().encode(headerPart + "." + payloadPart),
    signature,
  };
}

function decodeJson(part: string): Record<string, unknown> | undefined {
  const bytes = decodeBase64Url(part);
  if (bytes === undefined) {
    return undefined;
  }
  try {
    const value: unknown = JSON.parse(new TextDecoder().decode(bytes));
    return typeof value === "object" && value !== null && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : undefined;
  } catch {
    return undefined;
  }
}

function decodeBase64Url(part: string): BufferSource | undefined {
  if (part === "" || !/^[A-Za-z0-9_-]+$/.test(part)) {
    return undefined;
  }
  const base64 = part.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - (part.length % 4)) % 4);
  try {
    const binary = atob(base64);
    const bytes = new Uint8Array(new ArrayBuffer(binary.length));
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  } catch {
    return undefined;
  }
}

type KeySet = { keys: Map<string, CryptoKey>; fetchedAt: number };
// The helper's one network dependency is the issuer's JWKS at <issuer>/keys.
// Module-scope caches bound how often a process fetches it, no matter how
// many requests it serves: once, plus at most one refetch per cooldown
// window on an unknown kid, and nothing at all for a cooldown window after a
// failed fetch. A forged token with a made-up kid therefore cannot make the
// app hammer the issuer; it is reported as unknown_key.
const keySets = new Map<string, Promise<KeySet>>();
const failedAt = new Map<string, number>();

/** The issuer's key for kid, from the cached JWKS, refetched once per cooldown when kid is new. */
async function keyFor(issuer: string, kid: string | undefined): Promise<CryptoKey | undefined> {
  const cached = loadKeySet(issuer);
  let keySet = await cached;
  let key = pickKey(keySet, kid);
  if (key === undefined && Date.now() - keySet.fetchedAt > JWKS_REFETCH_COOLDOWN_MS) {
    if (keySets.get(issuer) === cached) {
      keySets.delete(issuer);
    }
    keySet = await loadKeySet(issuer);
    key = pickKey(keySet, kid);
  }
  return key;
}

function pickKey(keySet: KeySet, kid: string | undefined): CryptoKey | undefined {
  if (kid !== undefined) {
    return keySet.keys.get(kid);
  }
  return keySet.keys.size === 1 ? keySet.keys.values().next().value : undefined;
}

function loadKeySet(issuer: string): Promise<KeySet> {
  let pending = keySets.get(issuer);
  if (pending === undefined) {
    const lastFailure = failedAt.get(issuer);
    if (lastFailure !== undefined && Date.now() - lastFailure < JWKS_REFETCH_COOLDOWN_MS) {
      return Promise.reject(new Error("identity issuer fetch failed recently; not retrying yet"));
    }
    pending = fetchKeySet(issuer).catch((error: unknown) => {
      keySets.delete(issuer);
      failedAt.set(issuer, Date.now());
      throw error;
    });
    keySets.set(issuer, pending);
  }
  return pending;
}

async function fetchKeySet(issuer: string): Promise<KeySet> {
  const jwks = await fetchJson(issuer + "/keys");
  if (!Array.isArray(jwks.keys)) {
    throw new Error("identity issuer JWKS has no keys");
  }
  const keys = new Map<string, CryptoKey>();
  for (const candidate of jwks.keys as unknown[]) {
    const jwk = candidate as { kty?: unknown; kid?: unknown; n?: unknown; e?: unknown; alg?: unknown; use?: unknown };
    if (
      jwk.kty !== "RSA" ||
      typeof jwk.kid !== "string" ||
      typeof jwk.n !== "string" ||
      typeof jwk.e !== "string" ||
      (jwk.alg !== undefined && jwk.alg !== "RS256") ||
      (jwk.use !== undefined && jwk.use !== "sig")
    ) {
      continue;
    }
    keys.set(
      jwk.kid,
      await crypto.subtle.importKey(
        "jwk",
        { kty: "RSA", n: jwk.n, e: jwk.e, alg: "RS256", ext: true },
        { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
        false,
        ["verify"],
      ),
    );
  }
  return { keys, fetchedAt: Date.now() };
}

async function fetchJson(url: string): Promise<Record<string, unknown>> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
  try {
    const response = await fetch(url, { signal: controller.signal });
    if (!response.ok) {
      throw new Error("identity issuer returned " + response.status + " for " + url);
    }
    const value: unknown = await response.json();
    if (typeof value !== "object" || value === null) {
      throw new Error("identity issuer returned a non-object document");
    }
    return value as Record<string, unknown>;
  } finally {
    clearTimeout(timer);
  }
}

/** Accepts exactly the claim set Cursor issues; anything else is invalid_claims. */
function identityFromClaims(token: string, claims: IdentityClaims, source: TokenSource): Identity {
  const {
    sub,
    exp,
    email,
    email_verified: emailVerified,
    name,
    idp,
    app_visibility: appVisibility,
  } = claims;
  // Only the gate signs tokens, and it stamps every preview token's stage;
  // a token without one is from a gate that predates the claim.
  const stage: IdentityStage = claims.stage === "preview" ? "preview" : "production";
  if (
    typeof sub !== "string" ||
    typeof exp !== "number" ||
    typeof email !== "string" ||
    typeof emailVerified !== "boolean" ||
    typeof name !== "string" ||
    typeof idp !== "object" ||
    idp === null ||
    !("provider" in idp) ||
    idp.provider !== "cursor" ||
    !("sub" in idp) ||
    typeof idp.sub !== "string"
  ) {
    return { verified: false, reason: "invalid_claims" };
  }
  const base = {
    verified: true as const,
    simulated: false,
    token,
    sub,
    email,
    emailVerified,
    name,
    idp: { provider: "cursor" as const, sub: idp.sub },
    stage,
    expiresAt: new Date(exp * 1000),
    claims,
  };
  const personFormat =
    source === "person" ||
    (source === "forwarded" && claims.ver === undefined && claims.kind === undefined);
  if (personFormat) {
    if (claims.kind !== undefined && claims.kind !== "person") {
      return { verified: false, reason: "invalid_claims" };
    }
  } else if (claims.ver !== IDENTITY_VERSION) {
    return { verified: false, reason: "invalid_claims" };
  } else if (claims.kind === "key") {
    return keyIdentityFromClaims(base, claims);
  } else if (claims.kind !== "person") {
    return { verified: false, reason: "invalid_claims" };
  }
  const userId = /^user:(\d+)$/.exec(sub);
  if (userId === null) {
    return { verified: false, reason: "invalid_claims" };
  }
  const person = { ...base, kind: "person" as const, userId: Number(userId[1]) };
  if (appVisibility === "private") {
    return { ...person, appVisibility };
  }
  const { team_id: teamId, team_role: teamRole } = claims;
  if (
    appVisibility === "team" &&
    typeof teamId === "number" &&
    (teamRole === "admin" || teamRole === "member")
  ) {
    return { ...person, appVisibility, teamId, teamRole };
  }
  return { verified: false, reason: "invalid_claims" };
}

/**
 * An API key: no email, exactly one owner, and team claims only on a team
 * app, where its role is "service", so no key ever reads as a member or admin.
 */
function keyIdentityFromClaims(base: IdentityBase, claims: IdentityClaims): Identity {
  const {
    owner_user_id: ownerUserId,
    owner_team_id: ownerTeamId,
    app_visibility: appVisibility,
    team_id: teamId,
    team_role: teamRole,
  } = claims;
  const owner =
    typeof ownerUserId === "number" && ownerTeamId === undefined
      ? { ownerUserId }
      : typeof ownerTeamId === "number" && ownerUserId === undefined
        ? { ownerTeamId }
        : undefined;
  if (base.email !== "" || base.emailVerified !== false || owner === undefined) {
    return { verified: false, reason: "invalid_claims" };
  }
  const key = { ...base, email: "" as const, emailVerified: false as const, kind: "key" as const, ...owner };
  if (appVisibility === "team" && typeof teamId === "number" && teamRole === "service") {
    return { ...key, appVisibility, teamId, teamRole };
  }
  if (
    (appVisibility === "private" || appVisibility === "public") &&
    teamId === undefined &&
    teamRole === undefined
  ) {
    return { ...key, appVisibility };
  }
  return { verified: false, reason: "invalid_claims" };
}
